class Solution {
  public long numOfSubsequences(String s) {
    int n = s.length();
    long l = 0, lc = 0, lct = 0;
    for (int i = 0; i < n; i++) {
      char c = s.charAt(i);
      if (c == 'L') l++;
      else if (c == 'C') lc += l;
      else if (c == 'T') lct += lc;
    }
    long t = 0, ct = 0;
    for (int i = n - 1; i >= 0; i--) {
      char c = s.charAt(i);
      if (c == 'T') t++;
      else if (c == 'C') ct += t;
    }
    long gain = Math.max(ct, lc);
    long prefixL = 0, suffixT = t;
    for (int i = 0; i < n; i++) {
      gain = Math.max(gain, prefixL * suffixT);
      char c = s.charAt(i);
      if (c == 'T') suffixT--;
      else if (c == 'L') prefixL++;
    }
    return lct + gain;
  }
}
